/* eslint-disable no-console -- CLI entry point; stdout/stderr reporting is the whole job */
// The freshness watcher for the generated ADR index on main (Issue #3416,
// docs/adr/3416-regenerate-adr-index-daily-pr.md "仕組み", TPL-2786).
//
// main's index is regenerated by a daily routine, so it lags by up to a day,
// two when a run waits out the checks. This fails only when the oldest change
// main's index does not reflect is older than 50 hours: the routine stopped,
// or two runs in a row did not merge. One missed day is reported by the
// routine itself.
//
// Equivalently: main's generated files must equal a regeneration from the
// inputs of some first-parent commit of main no older than the 50-hour
// boundary, the newest commit at or before the boundary included (its inputs
// were current at the boundary). Commits with the same inputs regenerate once.
// No marker or trailer is trusted; the files are compared.
//
// The checkout's generator regenerates every candidate. When the generator
// version changed inside the window, an old input regenerated by the new
// generator would differ only in format, so the run passes with a notice and
// judges again once the upgrade is older than the window.

import {
  type Tree,
  adrPathsAt,
  checkoutGenerator,
  compareTrees,
  generatedTreeAt,
  generatorVersionAt,
  inputKey,
  regenerateAt,
} from "./regenerate-at.ts";
import { execFileSync } from "node:child_process";

export const WINDOW_HOURS = 50;

export interface Commit {
  sha: string;
  /** Committer time, seconds since the epoch (a squash merge's merge time). */
  time: number;
}

/**
 * The commits whose inputs may be what main's index reflects: the first-parent
 * history (newest first) back to and including the newest commit at or before
 * the boundary.
 */
export function windowCommits(history: readonly Commit[], now: number): Commit[] {
  const boundary = now - WINDOW_HOURS * 3600;
  const inWindow: Commit[] = [];
  for (const c of history) {
    inWindow.push(c);
    if (c.time <= boundary) break;
  }
  return inWindow;
}

export type Freshness =
  | { state: "fresh"; reflects: Commit }
  | { state: "skipped"; reason: string }
  | { state: "stale" };

export function judgeFreshness(input: {
  candidates: readonly Commit[];
  key: (sha: string) => string;
  matches: (sha: string) => boolean;
  generatorChanged: boolean;
}): Freshness {
  const seen = new Set<string>();
  for (const c of input.candidates) {
    const key = input.key(c.sha);
    if (seen.has(key)) continue;
    seen.add(key);
    if (input.matches(c.sha)) return { state: "fresh", reflects: c };
  }
  if (input.generatorChanged) {
    return {
      state: "skipped",
      reason: `the @kompiro/adr-tools version changed within the last ${WINDOW_HOURS} hours`,
    };
  }
  return { state: "stale" };
}

function main(): number {
  const now = Math.floor(Date.now() / 1000);
  const history: Commit[] = execFileSync(
    "git",
    ["log", "--first-parent", "--format=%H %ct", "HEAD"],
    { encoding: "utf-8", maxBuffer: 64 * 1024 * 1024 },
  )
    .split("\n")
    .filter((l) => l !== "")
    .map((l) => {
      const [sha, time] = l.split(" ");
      return { sha, time: Number(time) };
    });
  const head = history[0];
  const paths = adrPathsAt(head.sha);
  const committed = generatedTreeAt(head.sha, paths);
  const adr = checkoutGenerator();
  const candidates = windowCommits(history, now);
  const oldest = candidates.at(-1)!;

  const result = judgeFreshness({
    candidates,
    key: (sha) => inputKey(sha, paths),
    matches: (sha) => {
      let regenerated: Tree;
      try {
        regenerated = regenerateAt(sha, adrPathsAt(sha), adr);
      } catch (e) {
        // A generator that fails on every candidate also ends as "stale"; say why.
        const stderr = String((e as { stderr?: unknown }).stderr ?? "").trim();
        console.error(`regenerating ${sha} failed: ${stderr || (e as Error).message}`);
        return false;
      }
      return compareTrees(regenerated, committed).length === 0;
    },
    generatorChanged: generatorVersionAt(head.sha) !== generatorVersionAt(oldest.sha),
  });

  if (result.state === "fresh") {
    const age = ((now - result.reflects.time) / 3600).toFixed(1);
    console.log(
      `main's ADR index reflects the inputs of ${result.reflects.sha} (committed ${age} hours ago).`,
    );
    return 0;
  }
  if (result.state === "skipped") {
    console.log(`Freshness not judged: ${result.reason}.`);
    return 0;
  }
  const annotate = process.env.GITHUB_ACTIONS === "true" ? "::error::" : "";
  console.error(
    `${annotate}main's generated ADR index matches no main commit's inputs from the last ` +
      `${WINDOW_HOURS} hours: the daily regeneration has not merged for two days. Check the ` +
      "routine's runs, or run pnpm adr:regenerate-pr by hand (Issue #3416).",
  );
  return 1;
}

if (process.argv[1]?.endsWith("check-freshness.ts")) {
  process.exitCode = main();
}
